function makeTeardropGeometry(length = 1.05, radius = 0.45, radialSegments = 48, stacks = 42) {
  const verts = [];
  const indices = [];
  for (let i = 0; i <= stacks; i++) {
    const t = i / stacks;
    const y = length * t;
    const profile = radius * Math.pow(Math.sin(Math.PI * t), 0.48) * (0.54 + 0.72 * t);
    for (let j = 0; j <= radialSegments; j++) {
      const a = 2 * Math.PI * j / radialSegments;
      verts.push(profile * Math.cos(a), y, profile * Math.sin(a));
    }
  }
  const row = radialSegments + 1;
  for (let i = 0; i < stacks; i++) {
    for (let j = 0; j < radialSegments; j++) {
      const a = i * row + j;
      const b = a + row;
      indices.push(a, b, a + 1, b, b + 1, a + 1);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  g.setIndex(indices);
  g.computeVertexNormals();
  g.computeBoundingSphere();
  return g;
}

