  const guideA = rotateAboutBond(baseUpperGuideA, theta);
  const guideB = rotateAboutBond(baseUpperGuideB, theta);
  updateLine(upperGuide1, [upperC.clone(), upperC.clone().add(guideA.multiplyScalar(0.62))]);
  updateLine(upperGuide2, [upperC.clone(), upperC.clone().add(guideB.multiplyScalar(0.62))]);

  const guideFade = Math.max(0, 1 - currentAngle / 55);
  const offsetRed = baseOrbitalAxis.clone().multiplyScalar(0.72);
  const offsetBlue = baseOrbitalAxis.clone().multiplyScalar(-0.72);
  updateLine(overlapLineRed, [
    lowerC.clone().add(offsetRed).add(bondAxis.clone().multiplyScalar(-0.38)),
    upperC.clone().add(offsetRed).add(bondAxis.clone().multiplyScalar(0.38))
