    lowerC.clone().add(offsetBlue).add(bondAxis.clone().multiplyScalar(-0.38)),
    upperC.clone().add(offsetBlue).add(bondAxis.clone().multiplyScalar(0.38))
  ]);
  overlapLineRed.material.opacity = guideFade;
  overlapLineBlue.material.opacity = guideFade;

  const perpFade = Math.max(0, (currentAngle - 42) / 48);
  const pSide = bondAxis.clone().cross(upperAxis).normalize();
  updateLine(perpGuide1, [
    upperC.clone().add(upperAxis.clone().multiplyScalar(-0.52)),
    upperC.clone().add(upperAxis.clone().multiplyScalar(0.52))
  ]);
  updateLine(perpGuide2, [
    upperC.clone().add(pSide.clone().multiplyScalar(-0.38)),
    upperC.clone().add(pSide.clone().multiplyScalar(0.38))
  ]);
  perpGuide1.material.opacity = perpFade;
  perpGuide2.material.opacity = perpFade;

  const strength = Math.max(0, Math.cos(theta));
  barFill.scale.set(barW * strength, 1, 1);
  barFill.position.x = barLeft + (barW * strength) / 2;
  barFill.material.color.set(strength > 0.55 ? 0x45a85a : strength > 0.18 ? 0xe2a83b : 0xc84a4a);

  captionLabel.div.innerHTML = currentAngle < 70
    ? '<b>π bond</b><br><b>(<i>p</i> orbitals are parallel)</b>'
    : '<b>Broken π bond after rotation</b><br><b>(<i>p</i> orbitals are perpendicular)</b>';

  angleReadout.textContent = String(Math.round(currentAngle));
  slider.value = String(Math.round(currentAngle));
  stateSelect.value = currentAngle >= 70 ? 'Broken π bond after rotation' : 'Aligned p orbitals';
}

