const dashedBlackMatBase = new THREE.LineDashedMaterial({ color: 0x000000, dashSize: 0.075, gapSize: 0.055, transparent: true, opacity: 0.9 });

function makeTeardropGeometry(length = 1.05, radius = 0.45, radialSegments = 56, stacks = 48) {
  const verts = [];
  const indices = [];
  for (let i = 0; i <= stacks; i++) {
    const t = i / stacks;
    const y = length * t;
    const bulb = Math.sin(Math.PI * t);
    const asym = Math.pow(Math.max(t, 0.0001), 0.34) * (1.13 - 0.28 * t);
    const r = radius * Math.pow(Math.max(bulb, 0), 0.56) * asym;
    for (let j = 0; j <= radialSegments; j++) {
      const a = 2 * Math.PI * j / radialSegments;
      verts.push(r * Math.cos(a), y, r * Math.sin(a));
    }
  }
  const row = radialSegments + 1;
  for (let i = 0; i < stacks; i++) {
    for (let j = 0; j < radialSegments; j++) {
      const a = i * row + j;
      const b = a + row;
      indices.push(a, b, a + 1, b, b + 1, a + 1);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  return geom;
}

const lobeGeom = makeTeardropGeometry();
const dotGeom = new THREE.SphereGeometry(0.045, 20, 14);

function cylinderBetweenIn(group, a, b, radius, mat) {
  const dir = b.clone().sub(a);
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, dir.length(), 18), mat);
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(yUnit, dir.clone().normalize());
  group.add(mesh);
  return mesh;
}

function makePanel(name, xOffset) {
  const group = new THREE.Group();
  group.position.set(xOffset, 0, 0);
  scene.add(group);

  const redMat = redMatBase.clone();
  const blueMat = blueMatBase.clone();

  const lowerRed = new THREE.Mesh(lobeGeom, redMat);
  const lowerBlue = new THREE.Mesh(lobeGeom, blueMat);
  const upperRed = new THREE.Mesh(lobeGeom, redMat.clone());
  const upperBlue = new THREE.Mesh(lobeGeom, blueMat.clone());
  lowerRed.renderOrder = 2;
  lowerBlue.renderOrder = 1;
  upperRed.renderOrder = 4;
  upperBlue.renderOrder = 3;
  group.add(lowerRed, lowerBlue, upperRed, upperBlue);

  const lowerDot = new THREE.Mesh(dotGeom, blackMat);
  const upperDot = new THREE.Mesh(dotGeom, blackMat);
  group.add(lowerDot, upperDot);

  const lowerRedHi = new THREE.Mesh(new THREE.SphereGeometry(0.18, 24, 16), redHiMatBase.clone());
  const upperRedHi = new THREE.Mesh(new THREE.SphereGeometry(0.18, 24, 16), redHiMatBase.clone());
  const lowerBlueHi = new THREE.Mesh(new THREE.SphereGeometry(0.20, 24, 16), blueHiMatBase.clone());
  const upperBlueHi = new THREE.Mesh(new THREE.SphereGeometry(0.20, 24, 16), blueHiMatBase.clone());
  group.add(lowerRedHi, upperRedHi, lowerBlueHi, upperBlueHi);

  const sigmaBond = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([lowerC0, upperC0]),
    new THREE.LineBasicMaterial({ color: 0x000000 })
  );
  group.add(sigmaBond);

  cylinderBetweenIn(group, lowerC0, lowerC0.clone().add(new THREE.Vector3(-0.43, -0.17, 0.04)), 0.035, blackMat);
  cylinderBetweenIn(group, lowerC0, lowerC0.clone().add(new THREE.Vector3(0.41, -0.20, -0.02)), 0.035, blackMat);

  function makeLocalLine(mat) {
    const ln = new THREE.Line(new THREE.BufferGeometry(), mat);
    group.add(ln);
    return ln;
  }

  const upperStub1 = makeLocalLine(dashedBlackMatBase.clone());
  const upperStub2 = makeLocalLine(dashedBlackMatBase.clone());
  const overlapRed = makeLocalLine(thinBlackMatBase.clone());
  const overlapBlue = makeLocalLine(thinBlackMatBase.clone());
  const perp1 = makeLocalLine(dashedBlackMatBase.clone());
  const perp2 = makeLocalLine(dashedBlackMatBase.clone());
  perp1.material.opacity = 0;
  perp2.material.opacity = 0;

  const baseStubA = new THREE.Vector3(-0.62, 0.25, 0.02).normalize();
  const baseStubB = new THREE.Vector3(0.55, 0.28, -0.02).normalize();

  function updateLine(line, pts) {
    const old = line.geometry;
    line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
    old.dispose();
    line.computeLineDistances();
  }

  function setLobe(mesh, center, dir) {
    mesh.position.copy(center);
    mesh.quaternion.setFromUnitVectors(yUnit, dir.clone().normalize());
  }

  function rotateAboutBond(v, theta) {
    return v.clone().applyAxisAngle(bondAxis0, theta).normalize();
  }

  function placeHighlight(mesh, center, dir, phaseSign) {
    mesh.position.copy(center)
      .add(dir.clone().multiplyScalar(0.67))
      .add(new THREE.Vector3(0.13 * phaseSign, 0.055, 0.20 * phaseSign));
    mesh.scale.set(1.0, 0.55, 0.72);
  }

  setLobe(lowerRed, lowerC0, baseOrbitalAxis0);
  setLobe(lowerBlue, lowerC0, baseOrbitalAxis0.clone().negate());
  lowerDot.position.copy(lowerC0).add(baseOrbitalAxis0.clone().multiplyScalar(0.56));
  placeHighlight(lowerRedHi, lowerC0, baseOrbitalAxis0, 1);
  placeHighlight(lowerBlueHi, lowerC0, baseOrbitalAxis0.clone().negate(), -1);

  const lowerCLabel = addLabel('C', new THREE.Vector3(), { fontSize: '18px', bold: true, background: 'rgba(255,255,255,0.78)' });
  const upperCLabel = addLabel('C', new THREE.Vector3(), { fontSize: '18px', bold: true, background: 'rgba(255,255,255,0.78)' });

  function localToWorldPos(v) {
    group.updateMatrixWorld();
    return v.clone().applyMatrix4(group.matrixWorld);
  }

  function setLabelPositions() {
    lowerCLabel.pos.copy(localToWorldPos(lowerC0.clone().add(new THREE.Vector3(0.03, 0.02, 0.18))));
    upperCLabel.pos.copy(localToWorldPos(upperC0.clone().add(new THREE.Vector3(0.03, 0.02, 0.18))));
  }

  function setLabelOpacity(op) {
    lowerCLabel.div.style.opacity = op;
    upperCLabel.div.style.opacity = op;
  }

  function update(angleDeg) {
    const theta = THREE.MathUtils.degToRad(Math.max(0, Math.min(90, angleDeg)));
    const upperAxis = rotateAboutBond(baseOrbitalAxis0, theta);

    setLobe(upperRed, upperC0, upperAxis);
    setLobe(upperBlue, upperC0, upperAxis.clone().negate());
    upperDot.position.copy(upperC0).add(upperAxis.clone().multiplyScalar(0.56));
    placeHighlight(upperRedHi, upperC0, upperAxis, 1);
    placeHighlight(upperBlueHi, upperC0, upperAxis.clone().negate(), -1);

    const stubA = rotateAboutBond(baseStubA, theta);
    const stubB = rotateAboutBond(baseStubB, theta);
    updateLine(upperStub1, [upperC0.clone(), upperC0.clone().add(stubA.multiplyScalar(0.66))]);
    updateLine(upperStub2, [upperC0.clone(), upperC0.clone().add(stubB.multiplyScalar(0.66))]);

    const guideFade = Math.max(0, 1 - angleDeg / 45);
    const redEdge = baseOrbitalAxis0.clone().multiplyScalar(0.83).add(new THREE.Vector3(0.15, 0, 0.14));
    const blueEdge = baseOrbitalAxis0.clone().multiplyScalar(-0.83).add(new THREE.Vector3(-0.13, 0, -0.12));
