      upperC0.clone().add(blueEdge).add(bondAxis0.clone().multiplyScalar(0.33))
    ]);
    overlapRed.material.opacity = guideFade;
    overlapBlue.material.opacity = guideFade;

    const perpFade = Math.max(0, (angleDeg - 45) / 45);
    const pSide = bondAxis0.clone().cross(upperAxis).normalize();
    updateLine(perp1, [
      upperC0.clone().add(upperAxis.clone().multiplyScalar(-0.60)),
      upperC0.clone().add(upperAxis.clone().multiplyScalar(0.60))
    ]);
    updateLine(perp2, [
      upperC0.clone().add(pSide.clone().multiplyScalar(-0.43)),
      upperC0.clone().add(pSide.clone().multiplyScalar(0.43))
    ]);
    perp1.material.opacity = 0.88 * perpFade;
    perp2.material.opacity = 0.88 * perpFade;

    setLabelPositions();
  }

  registerInteractive(sigmaBond, {
    title: `${name}: C–C σ bond`,
    body: 'This diagonal carbon-carbon σ bond remains intact. The upper p orbital rotates about this bond axis.',
    tooltip: 'C–C σ bond: rotation axis'
