    tooltip: 'Rotating upper p orbital'
  });
  registerInteractive(lowerRed, {
    title: `${name}: fixed lower p orbital`,
    body: 'The lower p orbital stays fixed. Sideways overlap with a parallel upper p orbital gives the π bond.',
    tooltip: 'Fixed lower p orbital'
  });

  update(0);
  return { group, update, setLabelPositions, setLabelOpacity, labels: [lowerCLabel, upperCLabel] };
}

