window.goToStep = function goToStep(i) {
  const step = demoSteps[i] || demoSteps[0];
  comparisonMode = false;
  comparisonBox.checked = false;
  stepTitle.textContent = step.title;
  stepNarration.textContent = step.narration;
  const start = currentAngle;
  const end = Number(step.state.rotationAngle ?? currentAngle);
  const token = ++tweenToken;
  const t0 = performance.now();
  const dur = 650;
  function tick(now) {
    if (token !== tweenToken) return;
    const u = Math.min(1, (now - t0) / dur);
    const ease = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    currentAngle = start + (end - start) * ease;
    renderMode();
    if (u < 1) requestAnimationFrame(tick);
    else {
      currentAngle = end;
      if (step.state.orbitalState) stateSelect.value = step.state.orbitalState;
      renderMode();
    }
  }
  requestAnimationFrame(tick);
};

