function makeTeardropGeometry(length = 1.10, radius = 0.46, radialSegments = 64, stacks = 54) {
  const verts = [];
  const indices = [];
  for (let i = 0; i <= stacks; i++) {
    const t = i / stacks;
    const y = length * t;
    const pinch = Math.pow(Math.max(t, 0.0001), 0.36);
    const roundedTip = Math.pow(Math.max(1 - t, 0.0001), 0.20);
    const bulb = Math.sin(Math.PI * Math.pow(t, 0.78));
    const r = radius * Math.pow(Math.max(bulb, 0), 0.62) * pinch * roundedTip * (1.12 - 0.14 * t);
    for (let j = 0; j <= radialSegments; j++) {
      const a = (Math.PI * 2 * j) / radialSegments;
      verts.push(r * Math.cos(a), y, r * Math.sin(a));
    }
  }
  const row = radialSegments + 1;
  for (let i = 0; i < stacks; i++) {
    for (let j = 0; j < radialSegments; j++) {
      const a = i * row + j;
      const b = a + row;
      indices.push(a, b, a + 1, b, b + 1, a + 1);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  return geom;
}

