function updateBar(angleDeg) {
  const theta = THREE.MathUtils.degToRad(Math.max(0, Math.min(90, angleDeg)));
  const strength = Math.max(0, Math.cos(theta));
  const fillEnd = barLeft.clone().lerp(barRight, strength);
  updateCylinder(barFill, barLeft, fillEnd);
  barFill.visible = strength > 0.01;
  barFillMat.color.set(strength > 0.55 ? 0x4aa85a : strength > 0.18 ? 0xd99b2b : 0xc34a4a);
}

function updateCaption(angleDeg) {
  if (!captionLabel) return;
  if (angleDeg >= 70) {
    captionLabel.div.innerHTML = '<b>Broken π bond after rotation</b><br><b>(<i>p</i> orbitals are perpendicular)</b>';
  } else if (angleDeg <= 10) {
    captionLabel.div.innerHTML = '<b>π bond</b><br><b>(<i>p</i> orbitals are parallel)</b>';
  } else {
    captionLabel.div.innerHTML = '<b>π overlap reduced</b><br><b>(<i>p</i> orbitals are partly twisted)</b>';
  }
}

function updateLabels(upperAxis) {
  if (!lowerCLabel || !upperCLabel) return;
  lowerCLabel.pos.copy(lowerC).add(new THREE.Vector3(0.04, 0.02, 0.24));
  upperCLabel.pos.copy(upperC).add(new THREE.Vector3(0.04, 0.02, 0.24));
  lowerCLabel.div.style.opacity = 1;
  upperCLabel.div.style.opacity = 1;
}

function updateGuides(angleDeg, upperAxis) {
  const theta = THREE.MathUtils.degToRad(Math.max(0, Math.min(90, angleDeg)));
  const guideFade = Math.max(0, 1 - angleDeg / 45);
  const side = bondAxis.clone().cross(pAxis0).normalize();
  const redOuter1 = pAxis0.clone().multiplyScalar(0.72).add(side.clone().multiplyScalar(0.30));
  const redOuter2 = pAxis0.clone().multiplyScalar(0.72).add(side.clone().multiplyScalar(-0.30));
  const blueOuter1 = pAxis0.clone().multiplyScalar(-0.78).add(side.clone().multiplyScalar(0.27));
  const blueOuter2 = pAxis0.clone().multiplyScalar(-0.78).add(side.clone().multiplyScalar(-0.27));
  const offsets = [redOuter1, blueOuter1, redOuter2, blueOuter2];

  for (let i = 0; i < guideCylinders.length; i++) {
    const start = lowerC.clone().add(offsets[i]).add(bondAxis.clone().multiplyScalar(-0.52));
    const end = upperC.clone().add(offsets[i]).add(bondAxis.clone().multiplyScalar(0.52));
    updateCylinder(guideCylinders[i], start, end);
    guideCylinders[i].material.opacity = (i < 2 ? 0.98 : 0.55) * guideFade;
    guideCylinders[i].visible = guideFade > 0.02;
  }

  const stubA = rotateAboutBond(upperStubA0, theta);
  const stubB = rotateAboutBond(upperStubB0, theta);
  setDashedLine(upperStubA, [upperC, upperC.clone().add(stubA.multiplyScalar(0.66))]);
  setDashedLine(upperStubB, [upperC, upperC.clone().add(stubB.multiplyScalar(0.66))]);

  const perpFade = Math.max(0, (angleDeg - 45) / 45);
  const pSide = bondAxis.clone().cross(upperAxis).normalize();
  setDashedLine(perpGuideA, [
    upperC.clone().add(upperAxis.clone().multiplyScalar(-0.66)),
    upperC.clone().add(upperAxis.clone().multiplyScalar(0.66))
  ]);
  setDashedLine(perpGuideB, [
    upperC.clone().add(pSide.clone().multiplyScalar(-0.48)),
    upperC.clone().add(pSide.clone().multiplyScalar(0.48))
  ]);
  perpGuideA.material.opacity = 0.92 * perpFade;
  perpGuideB.material.opacity = 0.92 * perpFade;
}

function renderAngle(angleDeg) {
  currentAngle = Math.max(0, Math.min(90, Number(angleDeg) || 0));
  const theta = THREE.MathUtils.degToRad(currentAngle);
  const upperAxis = rotateAboutBond(pAxis0, theta);

  setLobe(lowerRed, lowerC, pAxis0);
  setLobe(lowerBlue, lowerC, pAxis0.clone().negate());
  setLobe(upperRed, upperC, upperAxis);
  setLobe(upperBlue, upperC, upperAxis.clone().negate());

  lowerDot.position.copy(lowerC).add(pAxis0.clone().multiplyScalar(0.55));
  upperDot.position.copy(upperC).add(upperAxis.clone().multiplyScalar(0.55));

  placeHighlight(lowerRedHi, lowerC, pAxis0, 1);
  placeHighlight(lowerBlueHi, lowerC, pAxis0.clone().negate(), -1);
  placeHighlight(upperRedHi, upperC, upperAxis, 1);
  placeHighlight(upperBlueHi, upperC, upperAxis.clone().negate(), -1);

  updateGuides(currentAngle, upperAxis);
  updateBar(currentAngle);
  updateCaption(currentAngle);
  updateLabels(upperAxis);

  document.getElementById('angleReadout').textContent = String(Math.round(currentAngle));
  document.getElementById('rotationAngle').value = String(Math.round(currentAngle));
  document.getElementById('orbitalState').value = currentAngle >= 70 ? 'Broken π bond after rotation' : 'Aligned p orbitals';
}

