function autoOrbitLoop() {
  requestAnimationFrame(autoOrbitLoop);
  if (!autoOrbit) return;
  const target = controls.target.clone();
  const rel = camera.position.clone().sub(target).applyAxisAngle(new THREE.Vector3(0, 1, 0), 0.0055);
  camera.position.copy(target).add(rel);
  camera.lookAt(target);
  controls.update();
}
